WITH filtered AS (SELECT *, COALESCE(unit_price, 0) AS unit_price_filled FROM order_items WHERE order_id = 30) SELECT CASE WHEN quantity >= 7 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(unit_price, 0.95) AS unit_price_p95, GROUPING_ID() AS gid FROM filtered GROUP BY CUBE (CASE WHEN quantity >= 7 THEN 'HIGH' ELSE 'LOW' END) ORDER BY distinct_ids DESC
